// The freeway data the game builds from (js/melbourne-freeways.js, generated by tools/melbourne/build-freeways.mjs), with
// the fixes that keep every drivable route open inside the playable area. js/freeways.js, js/freeway-footprint.js and
// js/city-grid.js import FREEWAYS from here, never from the generated file, so they all see the same ways and holes.
//
// The Burnley Tunnel (CityLink eastbound, from the Domain Tunnel's portals under Southbank) runs on far east under Richmond
// and comes up at Burnley, well past the east edge of the playable area (js/city-config.js getIslandBoundsAtZ). Driven
// as mapped, a car met the edge deep underground: a dead end it could not turn out of. Here the tunnel instead climbs at
// 6% to a portal and a short open cutting and comes up to the ground on the street at BURNLEY_EXIT, about 115 m inside
// the edge; the rest of it (and the tube beyond, way 87, out of bounds) no longer carries traffic, and the cutting's
// outline is added to the trenches (the holes in the land deck, js/city-grid.js), and the kerb islands and parks over it
// are cut round it (js/freeway-block-patches.js, by tools/melbourne/patch-cuttings.mjs).
import { FREEWAYS as RAW } from './melbourne-freeways.js';
import { BLOCK_PATCHES } from './freeway-block-patches.js';

const GRADE = 0.06; // the steepest grade on the network (tools/melbourne/refine-freeways.mjs)
const COVERED = -2.7; // deeper than this under the ground a way is cut-and-cover (refine-freeways.mjs)
const BURNLEY_START = [-247.9, 1125.7]; // the Burnley Tunnel's first sample (way 37)
const BURNLEY_EXIT = [1521.5, 1632.4]; // where it now comes up (a street, clear of the kerb islands either side)

function patch(raw) {
  const ways = raw.ways.slice(), trenches = (raw.trenches || []).slice();
  let chains = raw.chains;
  const wi = ways.findIndex(([, , , , f]) => Math.hypot(f[0] - BURNLEY_START[0], f[1] - BURNLEY_START[1]) < 1);
  if (wi < 0) return raw;
  const [name, kind, width, lanes, flat, opts] = ways[wi];
  const m = flat.length / 4;
  let k = 0, bd = Infinity;
  for (let i = 0; i < m; i++) { const d = Math.hypot(flat[i * 4] - BURNLEY_EXIT[0], flat[i * 4 + 1] - BURNLEY_EXIT[1]); if (d < bd) { bd = d; k = i; } }
  if (bd > 2 || k < 4) return raw;
  // the climb: back from the exit (at the ground) at GRADE until it meets the tunnel's own depth
  const f = flat.slice(0, (k + 1) * 4);
  let run = 0;
  for (let i = k; i >= 0; i--) {
    if (i < k) run += Math.hypot(f[i * 4 + 4] - f[i * 4], f[i * 4 + 5] - f[i * 4 + 1]);
    const h = -GRADE * run;
    if (h <= f[i * 4 + 2]) break;
    f[i * 4 + 2] = Math.round(h * 10) / 10;
    f[i * 4 + 3] = h < COVERED ? 1 : 0;
  }
  ways[wi] = [name, kind, width, lanes, f, opts];
  // the open cutting's outline (as refine-freeways.mjs traces them: half the width plus 1.6 m each side, a little past
  // each end)
  const open = [];
  for (let i = 0; i <= k; i++) if (f[i * 4 + 3] === 0 && f[i * 4 + 2] < -0.3) open.push(i);
  if (open.length) {
    const i0 = Math.max(0, open[0] - 1), i1 = k, left = [], right = [], o = width / 2 + 1.6;
    for (let i = i0; i <= i1; i++) {
      const a = Math.max(0, i - 1), b = Math.min(k, i + 1);
      const dx = f[b * 4] - f[a * 4], dz = f[b * 4 + 1] - f[a * 4 + 1], L = Math.hypot(dx, dz) || 1, nx = -dz / L, nz = dx / L;
      const e = i === i0 ? -1.5 : i === i1 ? 1.5 : 0, x = f[i * 4], z = f[i * 4 + 1];
      left.push([x + nx * o + (dx / L) * e, z + nz * o + (dz / L) * e]);
      right.push([x - nx * o + (dx / L) * e, z - nz * o + (dz / L) * e]);
    }
    trenches.push(left.concat(right.reverse()).flat());
  }
  // the traffic chain through the tunnel ends where it now comes up (the ways after it are out of bounds)
  chains = (raw.chains || []).map((c) => (c.includes(wi) ? c.slice(0, c.indexOf(wi) + 1) : c));
  return { ...raw, ways, trenches, chains };
}

// The refine pass's kerb-island patches, before the ones cut round the cuttings changed here (tools/melbourne/
// patch-cuttings.mjs, js/freeway-block-patches.js), which replace them block by block
export const RAW_PATCHES = RAW.blockPatches || {};
const patched = patch(RAW);
export const FREEWAYS = { ...patched, blockPatches: { ...RAW_PATCHES, ...BLOCK_PATCHES } };
